<template><main class="page"><h1>导出</h1><p class="muted">下载经过脱敏处理的治理结果。</p><section v-if="loading" class="state">加载中…</section><section v-else-if="error" class="state error">加载失败：{{error}}</section><section v-else-if="!rows.length" class="state">暂无可导出的数据</section><section v-else class="card"><h2>治理结果 CSV</h2><p>{{rows.length}} 条记录将导出为脱敏字段。</p><button data-testid="export-csv" class="primary" @click="download">导出脱敏 CSV</button><p class="muted">导出文件不包含原始敏感值。</p></section></main></template>
<script setup lang="ts">import {ref} from 'vue';const loading=ref(false),error=ref('');const rows=ref([{id:'r1',email:'u***@example.com',status:'valid'},{id:'r2',email:'a***@example.com',status:'duplicate'}]);function download(){const csv='id,email,status\n'+rows.value.map(r=>`${r.id},${r.email},${r.status}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='voicelens-sanitized.csv';a.click();URL.revokeObjectURL(a.href)}</script>
<style scoped>.page{max-width:760px;margin:auto;padding:32px}.card{background:var(--vl-surface);border:1px solid var(--vl-border);border-radius:12px;padding:24px}.primary{background:var(--vl-color-primary);color:#fff;border:0;padding:10px 16px;border-radius:8px}.muted{color:var(--vl-muted)}.state{text-align:center;padding:50px}.error{color:#b91c1c}</style>
